args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?spouse ?mother ?motherLabel WHERE {
  dbr:Louise_of_Mecklenburg-G%C3%BCstrow (dbo:spouse|dbp:spouse) ?spouse .
  ?spouse (dbo:mother|dbp:mother) ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
} LIMIT 10

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?mother ?motherLabel WHERE {
  {
    dbr:Louise_of_Mecklenburg-G%C3%BCstrow ^dbo:spouse ?spouse .
  } UNION {
    dbr:Louise_of_Mecklenburg-G%C3%BCstrow dbo:spouse ?spouse .
  } UNION {
    dbr:Louise_of_Mecklenburg-G%C3%BCstrow dbp:spouse ?spouse .
  }
  ?spouse (dbp:mother|dbo:mother|dbo:parent) ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
} LIMIT 10

